// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new ElementaryTransformation[]{}): a last tail
// that is not a list (of sort ElementaryTransformationList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcElementaryTransformationElementaryTransformationList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur ElementaryTransformationList = t
	for {
		c, ok := cur.(*ConcElementaryTransformationElementaryTransformationList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcElementaryTransformationElementaryTransformationList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concElementaryTransformation list is not a ElementaryTransformation", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

