func (t *ConcElementaryTransformationElementaryTransformationList) SetChildren(children []any) any {
	args := make([]ElementaryTransformation, len(children))
	for i, c := range children {
		args[i] = c.(ElementaryTransformation)
	}
	return MakeConcElementaryTransformation(args...)
}

func (t *ConcElementaryTransformationElementaryTransformationList) String() string {
	var b strings.Builder
	b.WriteString("concElementaryTransformation(")
	var cur ElementaryTransformationList = t
	for {
		c, ok := cur.(*ConcElementaryTransformationElementaryTransformationList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

