// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcElementaryTransformationElementaryTransformationList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []ElementaryTransformation
	var cur ElementaryTransformationList = t
	for {
		c, ok := cur.(*ConcElementaryTransformationElementaryTransformationList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcElementaryTransformationElementaryTransformationList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcElementaryTransformationElementaryTransformationList is Java Gom's concElementaryTransformation.fromTerm: an application of concElementaryTransformation, or a
// list (of ToATerm), of convertible elements.
func fromTermConcElementaryTransformationElementaryTransformationList(trm aterm.ATerm, conv aterm.ATermConverter) (res ElementaryTransformationList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concElementaryTransformation" {
		elems := make([]ElementaryTransformation, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = ElementaryTransformationFromTermConv(a, conv)
		}
		return MakeConcElementaryTransformation(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concElementaryTransformation (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []ElementaryTransformation
		for !list.IsEmpty() {
			elems = append(elems, ElementaryTransformationFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcElementaryTransformation(elems...), true
	}
	return nil, false
}

