// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcTomVisitTomVisitList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []TomVisit
	var cur TomVisitList = t
	for {
		c, ok := cur.(*ConcTomVisitTomVisitList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcTomVisitTomVisitList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcTomVisitTomVisitList is Java Gom's concTomVisit.fromTerm: an application of concTomVisit, or a
// list (of ToATerm), of convertible elements.
func fromTermConcTomVisitTomVisitList(trm aterm.ATerm, conv aterm.ATermConverter) (res TomVisitList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concTomVisit" {
		elems := make([]TomVisit, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = TomVisitFromTermConv(a, conv)
		}
		return MakeConcTomVisit(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concTomVisit (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []TomVisit
		for !list.IsEmpty() {
			elems = append(elems, TomVisitFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcTomVisit(elems...), true
	}
	return nil, false
}

