// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcTomEntryTomEntryList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []TomEntry
	var cur TomEntryList = t
	for {
		c, ok := cur.(*ConcTomEntryTomEntryList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcTomEntryTomEntryList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcTomEntryTomEntryList is Java Gom's concTomEntry.fromTerm: an application of concTomEntry, or a
// list (of ToATerm), of convertible elements.
func fromTermConcTomEntryTomEntryList(trm aterm.ATerm, conv aterm.ATermConverter) (res TomEntryList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concTomEntry" {
		elems := make([]TomEntry, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = TomEntryFromTermConv(a, conv)
		}
		return MakeConcTomEntry(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concTomEntry (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []TomEntry
		for !list.IsEmpty() {
			elems = append(elems, TomEntryFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcTomEntry(elems...), true
	}
	return nil, false
}

