// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcTomSymbolTomSymbolList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []TomSymbol
	var cur TomSymbolList = t
	for {
		c, ok := cur.(*ConcTomSymbolTomSymbolList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcTomSymbolTomSymbolList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcTomSymbolTomSymbolList is Java Gom's concTomSymbol.fromTerm: an application of concTomSymbol, or a
// list (of ToATerm), of convertible elements.
func fromTermConcTomSymbolTomSymbolList(trm aterm.ATerm, conv aterm.ATermConverter) (res TomSymbolList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concTomSymbol" {
		elems := make([]TomSymbol, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = TomSymbolFromTermConv(a, conv)
		}
		return MakeConcTomSymbol(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concTomSymbol (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []TomSymbol
		for !list.IsEmpty() {
			elems = append(elems, TomSymbolFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcTomSymbol(elems...), true
	}
	return nil, false
}

